/* @autogenerated */
import { startWebVitals, WebVital } from './web-vitals';

/** PerformanceObserver falso: guarda el callback de cada tipo para emitir entradas desde el test. */
class FakeObserver {
  static supportedEntryTypes = ['paint', 'largest-contentful-paint', 'layout-shift', 'event'];
  static callbacks: Record<string, (list: { getEntries: () => any[] }) => void> = {};
  constructor(private readonly callback: (list: { getEntries: () => any[] }) => void) {}
  observe(options: { type: string }) {
    FakeObserver.callbacks[options.type] = this.callback;
  }
}

const emit = (type: string, entries: any[]) => FakeObserver.callbacks[type]({ getEntries: () => entries });

describe('startWebVitals', () => {
  const original = window.PerformanceObserver;
  let vitals: WebVital[];

  beforeEach(() => {
    FakeObserver.callbacks = {};
    (window as any).PerformanceObserver = FakeObserver;
    vitals = [];
  });

  afterEach(() => {
    (window as any).PerformanceObserver = original;
  });

  /** Los listeners de página de otros tests siguen vivos: cada test recoge en su propio array. */
  const collect = () => {
    const own = vitals;
    return (vital: WebVital) => own.push(vital);
  };
  const byName = (name: string) => vitals.find((vital) => vital.name === name);

  it('reports the first byte and the first paint as they arrive, with their rating', () => {
    spyOn(performance, 'getEntriesByType').and.returnValue([{ responseStart: 900 }] as any);

    startWebVitals(collect());
    emit('paint', [
      { name: 'first-paint', startTime: 100 },
      { name: 'first-contentful-paint', startTime: 3500 },
    ]);

    expect(byName('TTFB')).toEqual(jasmine.objectContaining({ value: 900, rating: 'needs-improvement' }));
    expect(byName('FCP')).toEqual(jasmine.objectContaining({ value: 3500, rating: 'poor', route: location.pathname }));
  });

  it('reports LCP, CLS and INP once when the page is hidden', () => {
    spyOn(performance, 'getEntriesByType').and.returnValue([]);
    startWebVitals(collect());

    emit('largest-contentful-paint', [{ startTime: 1000 }, { startTime: 2000 }]);
    emit('largest-contentful-paint', []);
    emit('layout-shift', [
      { value: 0.05, hadRecentInput: false },
      { value: 0.5, hadRecentInput: true },
      { value: 0.0234, hadRecentInput: false },
    ]);
    emit('event', [{ duration: 80 }, { duration: 300 }]);
    window.dispatchEvent(new Event('pagehide'));
    window.dispatchEvent(new Event('pagehide'));

    expect(vitals.map((vital) => vital.name)).toEqual(['LCP', 'CLS', 'INP']);
    expect(byName('LCP')).toEqual(jasmine.objectContaining({ value: 2000, rating: 'good' }));
    expect(byName('CLS')).toEqual(jasmine.objectContaining({ value: 0.073, rating: 'good' }));
    expect(byName('INP')).toEqual(jasmine.objectContaining({ value: 300, rating: 'needs-improvement' }));
  });

  it('reports only CLS without paints nor interactions', () => {
    spyOn(performance, 'getEntriesByType').and.returnValue([]);
    startWebVitals(collect());

    window.dispatchEvent(new Event('pagehide'));

    expect(vitals.map((vital) => vital.name)).toEqual(['CLS']);
  });

  it('skips the metrics the browser does not support or fails to observe', () => {
    FakeObserver.supportedEntryTypes = ['paint'];
    spyOn(FakeObserver.prototype, 'observe').and.throwError('unsupported');
    spyOn(performance, 'getEntriesByType').and.returnValue([]);
    try {
      expect(() => startWebVitals(collect())).not.toThrow();
    } finally {
      FakeObserver.supportedEntryTypes = ['paint', 'largest-contentful-paint', 'layout-shift', 'event'];
    }
  });

  it('does nothing without PerformanceObserver', () => {
    (window as any).PerformanceObserver = undefined;

    startWebVitals(collect());

    expect(vitals).toEqual([]);
  });
});
